$read = static function (string $name) use ($root): array {
    $path = $root . '/storage/' . $name . '.json';
    if (!is_file($path)) return [];
    $value = json_decode((string) file_get_contents($path), true, 512, JSON_THROW_ON_ERROR);
    return is_array($value) ? array_values(array_filter($value, 'is_array')) : [];
};
$readArtifact = static function (string $name) use ($root): array {
    $path = $root . '/storage/' . $name . '.json';
    if (!is_file($path)) return [];
    $value = json_decode((string) file_get_contents($path), true, 512, JSON_THROW_ON_ERROR);
    if (!is_array($value)) return [];
    return array_is_list($value) ? (array) ($value[0] ?? []) : $value;
};
$write = static function (string $name, array $rows) use ($root): void {
    $path = $root . '/storage/' . $name . '.json';
    $temp = $path . '.batch644.' . bin2hex(random_bytes(5)) . '.tmp';
    $json = json_encode(array_values($rows), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR) . PHP_EOL;
    if (file_put_contents($temp, $json, LOCK_EX) === false || !rename($temp, $path)) {
        @unlink($temp);
        throw new RuntimeException('Unable to atomically write ' . $path);
    }
};
$hash = static fn(mixed $value): string => hash('sha256', json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR));
$norm = static function (string $text): string {
    $text = strtolower($text);
    $text = preg_replace('/\b\d+(?:[.,]\d+)?\b/u', '#', $text) ?? $text;
    $text = preg_replace('/[^a-z#]+/u', ' ', $text) ?? $text;
    return trim(preg_replace('/\s+/u', ' ', $text) ?? $text);
};
$normDuplicate = static function (string $text): string {
    $text = strtolower($text);
    $text = preg_replace('/[^a-z0-9]+/u', ' ', $text) ?? $text;
    return trim(preg_replace('/\s+/u', ' ', $text) ?? $text);
};
$stableText = static function (array $question): string {
    return strtolower(trim(implode(' ', [
        (string) ($question['question'] ?? ''),
        (string) ($question['answer'] ?? ''),
        (string) ($question['explanation'] ?? ''),
    ])));
};

