$sourceRole = static function (array $source): string {
    $type = strtoupper((string) ($source['source_type'] ?? ''));
    if (str_contains($type, 'OFFICIAL') || $type === 'PRIMARY_LAW') return 'PRIMARY_OFFICIAL';
    if (str_contains($type, 'ACADEMIC')) return 'ACADEMIC';
    $authority = strtolower((string) ($source['authority'] ?? ''));
    if (str_contains($authority, 'nist') || str_contains($authority, 'standards') || str_contains($authority, 'university') || str_contains($authority, 'openstax') || str_contains($authority, 'b c c')) return 'AUTHORITATIVE_TECHNICAL';
    return 'PROFESSIONAL_REFERENCE';
};

