$calculate = static function (array $question, string $leafId = ''): array {
    $text = strtolower(implode(' ', [(string)($question['question']??''),(string)($question['explanation']??'')]));
    $numeric = ($question['numeric'] ?? false) === true;
    if (!$numeric) return ['class'=>'NON_CALCULATION','family'=>'none','payload_status'=>'NOT_RECORDED'];
    $families = [
        'economics'=>'/(?:interest|annuit|present worth|depreciat|break.?even|eoq|ordering cost|holding cost|total operating cost)/',
        'algebra_geometry'=>'/(?:quadratic|polynomial|perimeter|area|trigonometric|logarithm|roots? of)/',
        'calculus'=>'/(?:derivative|integral|rate of change|accumulat|optimization)/',
        'statistics'=>'/(?:probability|confidence interval|sampling|regression|standard deviation|population variance|z.score|least.squares|arithmetic mean|mean and median)/',
        'stress_strain'=>'/(?:stress|strain|bending|torsion|deflection|buckling|fatigue)/',
        'fluid_flow'=>'/(?:flow rate|reynolds|darcy|bernoulli|pressure|head loss|jet)/',
        'thermodynamics'=>'/(?:thermodynamic|internal energy|entropy|enthalpy|ideal gas|energy balance)/',
        'heat_transfer'=>'/(?:heat transfer|thermal resistance|heat exchanger|radiation|conduction|convection)/',
        'cycles_engines'=>'/(?:cycle|engine|boiler|turbine|combustion|brake power)/',
        'machine_power'=>'/(?:shaft|gear|torque|rpm|power transmission|spring|bearing|flywheel)/',
        'manufacturing'=>'/(?:machin|cutting speed|feed rate|tolerance|eoq|production rate|cycle time)/',
        'reliability'=>'/(?:mtbf|mttr|failure rate|availability|reliability|process capability|control chart|cpk|fmea)/',
        'metrology'=>'/(?:measurement uncertainty|relative uncertainty|calibration|tolerance|gauge|measurement)/',
        'production_systems'=>'/(?:acceptable parts|production line|bottleneck|throughput|takt|inventory|eoq|work in process|capacity|shift)/',
    ];
    foreach ($families as $family=>$pattern) if (preg_match($pattern,$text)===1) return ['class'=>'CALCULATION_REQUIRED','family'=>$family,'payload_status'=>'NO_STRUCTURED_PAYLOAD_FIELD'];
    $leafFamily=match($leafId){
        'b644-me-math-statistics-numerical-methods'=>'statistics',
        'b644-me-engineering-economics'=>'economics',
        'b644-me-math-algebra-trigonometry','b644-me-math-analytic-geometry'=>'algebra_geometry',
        'b644-me-math-calculus-models'=>'calculus',
        'b644-me-math-vectors-linear-algebra','b644-me-basic-engineering-sciences','b644-me-engineering-mechanics','b644-me-mechanism-kinematics'=>'engineering_mechanics',
        'b644-me-strength-materials','b644-me-machine-design-stress-analysis','b644-me-stability-fatigue'=>'stress_strain',
        'b644-me-fluid-mechanics','b644-me-fluid-machinery'=>'fluid_flow',
        'b644-me-thermodynamics'=>'thermodynamics','b644-me-heat-transfer'=>'heat_transfer',
        'b644-me-power-cycles','b644-me-internal-combustion-engines','b644-me-power-fuels-combustion','b644-me-steam-power-boilers','b644-me-power-load-performance','b644-me-gas-combined-cycle','b644-me-hydroelectric-plants'=>'cycles_engines',
        'b644-me-machine-power-transmission','b644-me-bearings-lubrication'=>'machine_power',
        'b644-me-manufacturing-shop-practice'=>'manufacturing','b644-me-production-systems'=>'production_systems',
        'b644-me-quality-reliability-maintenance'=>'reliability','b644-me-tolerances-metrology'=>'metrology',
        default=>'numerical_interpretation_unclassified',
    };
    return ['class'=>'CONCEPTUAL_QUANTITATIVE','family'=>$leafFamily,'payload_status'=>'NO_STRUCTURED_PAYLOAD_FIELD'];
};

